// El escalador manda un candidato por peticion: cada aprobacion es una
// ejecucion independiente que espera su propia respuesta.
const c = $json.body ?? $json;
if (!c.ip) {
  throw new Error('Payload del escalador sin ip');
}
return [{ json: c }];

const c = $('Normalizar').first().json;

// "Pedir aprobacion" (sendAndWait) siempre envia con parse_mode Markdown y no se puede cambiar
// (n8n lo fija en createSendAndWaitMessageBody). Un "_", "*", "`" o "[" suelto en una ruta o un motivo
// hacia fallar el mensaje, y con el la propuesta. Ademas Telegram autoenlaza dominios e IPs.
// - md():    escapa los caracteres de Markdown y corta el autolink con U+2060 (texto libre).
// - code():  valores tecnicos entre backticks: no se enlazan y se copian limpios.
const md = v => String(v ?? '')
  .replace(/([_*`\[])/g, '\\$1')
  .replace(/([A-Za-z0-9-])\.(?=[A-Za-z0-9-])/g, '$1.⁠')
  .replace(/:\/\//g, ':⁠//')
  .replace(/@/g, '@⁠');
const code = v => '`' + String(v ?? '').replace(/`/g, "'").slice(0, 160) + '`';

// Cada enriquecimiento es opcional: si una API falla o no tiene datos, la
// propuesta sale igual. Prefiero una alerta pobre a ninguna.
const leer = (nodo) => { try { return $(nodo).first().json ?? {}; } catch (err) { return {}; } };
const abuse = leer('AbuseIPDB').data ?? {};
const gn = leer('GreyNoise');
const sh = leer('Shodan InternetDB');

const score = abuse.abuseConfidenceScore;
const origen = [abuse.countryCode, abuse.isp || abuse.domain].filter(Boolean).join(', ');

const l = [
  (c.prueba ? '\\[PRUEBA] ' : '') + '*Propuesta de bloqueo en Cloudflare*',
  '',
  'IP: ' + code(c.ip) + (origen ? ' (' + md(origen) + ')' : ''),
  'AbuseIPDB: ' + (Number.isFinite(Number(score)) && score !== null && score !== undefined ? Number(score) : 'n/d') + '/100' +
    (abuse.totalReports ? ' - ' + Number(abuse.totalReports) + ' reportes' : ''),
];

// GreyNoise separa el ruido de fondo de internet de lo dirigido contra ti:
// es lo que decide si esto merece tu atencion o es un bot mas.
if (gn.classification) {
  l.push('GreyNoise: ' + md(gn.classification)
    + (gn.name && gn.name !== 'unknown' ? ' - ' + md(String(gn.name).slice(0, 80)) : '')
    + (gn.noise ? ' (escanea internet entero)' : ' (NO es escaneo masivo: dirigido)'));
} else {
  l.push('GreyNoise: sin datos (no observada escaneando internet)');
}

// Shodan dice que ES la maquina atacante: casi siempre un servidor ajeno comprometido.
if (Array.isArray(sh.ports) && sh.ports.length) {
  const partes = ['puertos ' + sh.ports.slice(0, 8).map(Number).join(', ')];
  if (sh.cpes && sh.cpes.length) partes.push(sh.cpes.slice(0, 2).map(code).join(', '));
  if (sh.vulns && sh.vulns.length) partes.push(sh.vulns.length + ' CVE conocidos');
  if (sh.hostnames && sh.hostnames.length) partes.push(code(sh.hostnames[0]));
  l.push('Shodan: ' + partes.join(' - '));
}

l.push('', 'Motivos:', ...(c.motivos || []).slice(0, 10).map((m) => '- ' + md(String(m).slice(0, 300))));
if (c.rutas && c.rutas.length) {
  l.push('', 'Rutas: ' + c.rutas.slice(0, 8).map(code).join(', ') + (c.rutas.length > 8 ? ' y ' + (c.rutas.length - 8) + ' mas' : ''));
}
if (c.reglas && c.reglas.length) l.push('Reglas WAF: ' + c.reglas.slice(0, 8).map(code).join(', '));
if (c.primera) l.push('', 'Actividad: ' + md(c.primera) + ' -> ' + md(c.ultima));
l.push('', c.dias > 0
  ? 'Si apruebas: bloqueo en el borde durante ' + Number(c.dias) + ' dias; despues se retira solo.'
  : 'Si apruebas: se crea la regla y el job de vencimiento la retira hoy mismo.');
if (c.pendientes) l.push('(' + Number(c.pendientes) + ' candidatos mas esperan la proxima corrida)');
l.push('Sin respuesta en 24 h no se bloquea nada.');

return [{ json: { ...c, abuse_score: score ?? null, mensaje: l.join('\n') } }];

// Solo un 'Bloquear' explicito aplica la regla. 'Ignorar' o 24 h sin
// respuesta terminan aqui: devolver una lista vacia detiene el flujo.
if ($json.data?.approved !== true) {
  return [];
}

const c = $('Mensaje').first().json;

// Zone ID del sitio (Overview del dominio en Cloudflare). No es secreto.
const ZONE_TAG = '<CF_ZONE_ID>';

const exp = new Date(Date.now() + c.dias * 86400000).toISOString().slice(0, 10);

return [{
  json: {
    ip: c.ip,
    exp,
    zone: ZONE_TAG,
    cuerpo: {
      mode: 'block',
      configuration: { target: c.version === 6 ? 'ip6' : 'ip', value: c.ip },
      // El job de vencimiento reconoce las reglas propias por este prefijo.
      notes: 'nx-escalado exp=' + exp + ' | ' + ((c.motivos || [])[0] || '').slice(0, 120),
    },
  },
}];

const p = $('Preparar regla').first().json;
const r = $json;
const esc = v => String(v ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

// La API de Cloudflare informa el resultado en el cuerpo (success/errors),
// no solo en el status: por eso se lee aqui en vez de fiarse del HTTP.
let texto;
if (r.success === true) {
  texto = '✅ Bloqueada <code>' + esc(p.ip) + '</code> en el borde de Cloudflare hasta ' + esc(p.exp) + '.';
} else {
  const errs = (r.errors || []).map((e) => e.message || e.code).join('; ');
  texto = /duplicate|already exists/i.test(errs)
    ? '<code>' + esc(p.ip) + '</code> ya tenía una regla en Cloudflare; no se duplicó.'
    : '❌ NO se pudo bloquear <code>' + esc(p.ip) + '</code>: ' + esc(errs || JSON.stringify(r).slice(0, 200));
}
return [{ json: { texto } }];
